const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const grafton = ee.Geometry.Point([152.93, -29.69]);
  const canberra = ee.Geometry.Point([149.13, -35.28]);
  const startDate = '2020-01-15';
  const endDate = '2020-01-22'; // Exclusive end date

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate);

  const collectionSize = chirps.size().getInfo();
  console.log(`Collection size: ${collectionSize} images`);

  if (collectionSize === 0) {
    console.log("No data found for the specified period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum precipitation over the period
  const totalPrecip = chirps.select('precipitation').sum();

  // 4. Calculate total rainfall for both locations
  const graftonResult = totalPrecip.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: grafton,
    scale: 5566,
    maxPixels: 1e9
  }).get('precipitation');

  const canberraResult = totalPrecip.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: canberra,
    scale: 5566,
    maxPixels: 1e9
  }).get('precipitation');

  const graftonTotal = graftonResult.getInfo();
  const canberraTotal = canberraResult.getInfo();

  // 5. Validation & Final Answer
  console.log(`Grafton total rainfall: ${graftonTotal !== null ? graftonTotal.toFixed(2) : 'null'} mm`);
  console.log(`Canberra total rainfall: ${canberraTotal !== null ? canberraTotal.toFixed(2) : 'null'} mm`);

  if (graftonTotal === null || canberraTotal === null || 
      isNaN(graftonTotal) || isNaN(canberraTotal)) {
    console.log("Calculation failed - invalid result.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (graftonTotal < 0 || canberraTotal < 0 || 
      graftonTotal > 1000 || canberraTotal > 1000) {
    console.log("Invalid precipitation values detected.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (graftonTotal > canberraTotal) {
    console.log(`Grafton (${graftonTotal.toFixed(2)} mm) > Canberra (${canberraTotal.toFixed(2)} mm)`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`Grafton (${graftonTotal.toFixed(2)} mm) <= Canberra (${canberraTotal.toFixed(2)} mm)`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
